    .radio { width: 16px; height: 16px; flex-shrink: 0; border: 1px solid var(--border); border-radius: 50%; display: grid; place-items: center; }
    .radio::after { content: ''; width: 8px; height: 8px; border-radius: 50%; background: var(--accent); transform: scale(0); transition: transform var(--transition); }
    .choice:hover .choice-content { border-color: var(--accent); background: var(--selected); }
    .choice input:checked + .choice-content { background: var(--selected); border-color: var(--accent); }
