    .stepper input { appearance: textfield; -moz-appearance: textfield; width: 48px; border: 0; border-left: 1px solid var(--rule); border-right: 1px solid var(--rule); color: var(--ink); background: transparent; text-align: center; font-variant-numeric: tabular-nums; }
