    .primary:hover { background: var(--accent-hover); }
    .primary:active { transform: translateY(1px); }
    .primary svg { width: 16px; height: 16px; }
    .save-note { margin: var(--space-3) 0 0; color: var(--muted); text-align: center; font-size: 11px; }
    .error { color: var(--error); font-size: 12px; margin: var(--space-2) 0 0; }
    [aria-invalid=true] { border-color: var(--error) "'!important; }
    .closing { text-align: center; margin: var(--space-5) 0 0; color: var(--muted); font: italic 400 20px/1.2 var(--serif); }
    .footer { margin: var(--space-5) 0 0; text-align: center; font-size: 10px; letter-spacing: .2em; color: var(--muted); text-transform: uppercase; }
    .botanical { position: absolute; z-index: -1; color: var(--ornament); width: 300px; height: 510px; opacity: .55; pointer-events: none; }
    .botanical.left { left: max(-100px, calc(50% - 640px)); bottom: 45px; transform: rotate(-14deg); }
    .botanical.right { right: max(-120px, calc(50% - 650px)); top: 20px; transform: rotate(158deg); }
    .confirmation { padding: var(--space-5) 0 var(--space-7); text-align: center; }
    .confirmation .check { width: 48px; height: 48px; color: var(--accent); margin: 0 auto var(--space-5); }
    .confirmation h2 { margin-bottom: var(--space-4); }
    .confirmation p { color: var(--muted); margin: 0 0 var(--space-5); }
    .confirmation .primary { margin-top: var(--space-6); }
    .summary { display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-3); text-align: left; padding: var(--space-5) 0; border-top: 1px solid var(--rule); border-bottom: 1px solid var(--rule); margin: var(--space-5) 0; overflow-wrap: anywhere; }
    .summary dt { font-size: 12px; color: var(--muted); }
    .summary dd { margin: 0; text-align: right; }
    @media (min-width: 1600px) { .page { padding-top: var(--space-8); } }
    @media (max-width: 700px) {
      .page { padding: var(--space-4) var(--space-3) var(--space-5); }
      .stationery { padding: var(--space-6) var(--space-5); }
      .stationery::before { inset: 7px; }
      .botanical { display: none; }
      h1 { font-size: clamp(48px, 11vw, 64px); }
      .sprig { height: 56px; margin-bottom: var(--space-3); }
      .choice-content { gap: var(--space-2); font-size: 11px; padding: var(--space-3) var(--space-2); }
      .choices { gap: var(--space-2); }
