    @media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition: none !important; } }
  </style>
</head>
<body>
  <svg width="0" height="0" style="position:absolute" aria-hidden="true"><defs>
    <path id="oak-leaf" d="M0 0 C-5-7-16-5-15-12 C-22-12-24-19-17-23 C-24-28-20-35-12-33 C-17-40-10-45-5-40 C-8-49-1-53 2-45 C8-49 13-43 9-36 C18-39 23-33 16-27 C24-26 24-18 17-16 C22-10 16-4 10-7 C10-2 5 1 0 0Z"/>
    <g id="branch" fill="none" stroke="currentColor" stroke-width="1.25" stroke-linecap="round" stroke-linejoin="round">
      <path d="M145 480 C132 393 164 303 130 218 C111 168 107 100 125 34 M144 404 Q93 368 62 315 M145 357 Q196 325 217 269 M144 297 Q100 259 68 213 M130 227 Q183 196 200 146 M116 164 Q80 135 62 91 M117 110 Q159 85 168 45"/>
      <g fill="var(--canvas)">
        <use href="#oak-leaf" transform="translate(70 328) rotate(-43) scale(1.25)"/><use href="#oak-leaf" transform="translate(99 367) rotate(-72) scale(1.2)"/>
        <use href="#oak-leaf" transform="translate(144 405) rotate(37) scale(1.35)"/><use href="#oak-leaf" transform="translate(192 319) rotate(35) scale(1.3)"/>
        <use href="#oak-leaf" transform="translate(213 278) rotate(32) scale(1.15)"/><use href="#oak-leaf" transform="translate(115 270) rotate(-61) scale(1.2)"/>
        <use href="#oak-leaf" transform="translate(76 226) rotate(-41) scale(1.2)"/><use href="#oak-leaf" transform="translate(167 200) rotate(35) scale(1.3)"/>
        <use href="#oak-leaf" transform="translate(197 159) rotate(28) scale(1.1)"/><use href="#oak-leaf" transform="translate(85 139) rotate(-53) scale(1.15)"/>
        <use href="#oak-leaf" transform="translate(65 102) rotate(-35)"/><use href="#oak-leaf" transform="translate(145 93) rotate(40)"/>
        <use href="#oak-leaf" transform="translate(165 54) rotate(25) scale(.9)"/><use href="#oak-leaf" transform="translate(123 48) rotate(5)"/>
      </g>
      <path d="M92 355l-8-14m104-27 14-15M104 260l-17-24m80-40 17-20M86 134l-12-18m70-29 11-15"/>
      <path d="M122 340c-4-18-19-19-23-7-4 13 10 22 16 22 5-4 7-9 7-15Z M100 331q9-6 20 5 M113 324l3-8" fill="var(--canvas)"/>
    </g>
  </defs></svg>
  <main class="page">
    <svg class="botanical left" viewBox="0 0 280 510" aria-hidden="true"><use href="#branch"/></svg>
    <svg class="botanical right" viewBox="0 0 280 510" aria-hidden="true"><use href="#branch"/></svg>
    <article class="stationery" aria-labelledby="couple">
      <header class="invitation">
        <svg class="sprig" viewBox="0 0 160 70" fill="none" stroke="currentColor" stroke-width="1" aria-hidden="true">
          <path d="M25 57Q75 59 131 17M57 51 49 29M77 43 80 20M97 33l20 3M112 25l2-12"/>
          <g fill="var(--paper)">
            <use href="#oak-leaf" transform="translate(52 37) rotate(-29) scale(.57)"/>
            <use href="#oak-leaf" transform="translate(79 28) rotate(12) scale(.55)"/>
            <use href="#oak-leaf" transform="translate(106 34) rotate(82) scale(.55)"/>
            <use href="#oak-leaf" transform="translate(119 25) rotate(48) scale(.5)"/>
          </g>
          <path d="M58 47c-5-7-13-4-12 2 1 7 8 10 12 7 2-3 2-6 0-9Z M46 48q5-4 12-1M51 44l-2-5"/>
        </svg>
        <p class="eyebrow">Together with our families</p>
        <h1 id="couple">Sam <span class="amp">&amp;</span> Priya</h1>
        <p class="date"><time datetime="2027-06-14T16:00:00-04:00">JUNE 14, 2027 <span class="dot">·</span> 4:00 PM</time></p>
        <p class="venue">Hollow Oak Farm</p>
        <p class="location">Hudson, New York</p>
      </header>
      <div class="divider" aria-hidden="true"><svg viewBox="0 0 24 16" fill="none" stroke="currentColor"><path d="M2 13Q12 12 21 3M7 11Q3 5 10 6Q12 10 7 11ZM13 8Q11 1 17 2Q20 6 13 8Z"/></svg></div>
      <section id="form-section" aria-labelledby="rsvp-heading">
        <h2 id="rsvp-heading">Kindly RSVP</h2>
        <form id="rsvp-form" novalidate>
          <div class="field">
            <label class="label" for="guest-name">Your full name</label>
            <input id="guest-name" name="name" type="text" autocomplete="name" placeholder="First and last name" required maxlength="200" aria-describedby="name-error">
            <p class="error" id="name-error" hidden>Please enter your name.</p>
          </div>
          <fieldset aria-describedby="attendance-error">
            <legend>Will you be joining us?</legend>
            <div class="choices">
              <label class="choice"><input type="radio" name="attendance" value="yes" required><span class="choice-content"><span class="radio" aria-hidden="true"></span>Joyfully accepts</span></label>
              <label class="choice"><input type="radio" name="attendance" value="no"><span class="choice-content"><span class="radio" aria-hidden="true"></span>Regretfully declines</span></label>
            </div>
            <p class="error" id="attendance-error" hidden>Please choose whether you’ll be attending.</p>
          </fieldset>
          <div id="attending-fields">
            <div class="field">
              <label class="label" for="guest-count">Number of guests</label>
              <div class="guest-row">
                <div class="stepper">
                  <button type="button" id="decrease" aria-label="Remove one guest" disabled>−</button>
                  <input type="number" id="guest-count" name="guests" min="1" step="1" value="1" required aria-describedby="guest-hint guest-error">
                  <button type="button" id="increase" aria-label="Add one guest">+</button>
                </div>
                <span class="hint" id="guest-hint">Including you</span>
              </div>
              <p class="error" id="guest-error" hidden>Please enter a whole number of at least 1.</p>
            </div>
            <div class="field">
              <label class="label" for="dietary">Dietary needs <span class="optional">(optional)</span></label>
              <textarea id="dietary" name="dietary" rows="2" maxlength="2000" placeholder="Any allergies or dietary preferences in your party?"></textarea>
            </div>
          </div>
          <p class="error" id="save-error" role="alert" hidden>Your browser couldn’t save your response. Please allow local storage and try again.</p>
          <button class="primary" type="submit">Save my RSVP <svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.3" aria-hidden="true"><path d="M3 10h13m-5-5 5 5-5 5"/></svg></button>
          <p class="save-note">Saved on this device only. Not sent to Sam &amp; Priya.</p>
        </form>
      </section>
      <section class="confirmation" id="confirmation" aria-labelledby="confirmation-heading" hidden>
        <svg class="check" viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-width="1.3" aria-hidden="true"><circle cx="24" cy="24" r="22"/><path d="m14 24 7 7 14-15"/></svg>
        <h2 id="confirmation-heading" tabindex="-1">Your RSVP is saved</h2>
        <p id="confirmation-message"></p>
        <dl class="summary" id="response-summary"></dl>
        <p class="save-note">Saved on this device only.<br>Your response has not been sent to Sam &amp; Priya.</p>
        <button class="primary" type="button" id="edit-response">Edit my response</button>
      </section>
      <p class="closing">With love, Sam &amp; Priya</p>
    </article>
    <p class="footer">Sam &amp; Priya <span aria-hidden="true"> · </span> June 2027</p>
  </main>
  <script>
    (() => {
      const storageKey = '"'sam-priya-wedding-rsvp-2027';
      const form = document.getElementById('rsvp-form');
      const name = document.getElementById('guest-name');
      const count = document.getElementById('guest-count');
      const dietary = document.getElementById('dietary');
      const decrease = document.getElementById('decrease');
      const attendingFields = document.getElementById('attending-fields');
      const formSection = document.getElementById('form-section');
      const confirmation = document.getElementById('confirmation');
      const attendance = () => form.querySelector('input[name=\"attendance\"]:checked')?.value;
      function setError(input, id, invalid) {
        document.getElementById(id).hidden = "'!invalid;
        if (invalid) input.setAttribute('"'aria-invalid', 'true');
        else input.removeAttribute('aria-invalid');
      }
      function validateName() {
        const valid = name.value.trim().length > 0;
        setError(name, 'name-error', "'!valid);
        return valid;
      }
      function validateCount() {
        const valid = Number.isSafeInteger(Number(count.value)) && Number(count.value) >= 1;
        setError(count, '"'guest-error', "'!valid);
        return valid;
      }
      function updateCount() { decrease.disabled = Number(count.value) <= 1 || !count.value; }
      function updateAttendance() {
        const declined = attendance() === '"'no';
        attendingFields.hidden = declined;
        count.disabled = declined;
        dietary.disabled = declined;
        document.getElementById('attendance-error').hidden = true;
        form.querySelectorAll('[name=\"attendance\"]').forEach(input => input.removeAttribute('aria-invalid'));
      }
      function showConfirmation(response, focus = true) {
        formSection.hidden = true;
        confirmation.hidden = false;
        document.getElementById('confirmation-message').textContent = response.attendance === 'yes' ? 'A celebration to look forward to.' : 'You’ll be with us in spirit.';
        const summary = document.getElementById('response-summary');
        summary.replaceChildren();
        const details = [['Name', response.name], ['Attendance', response.attendance === 'yes' ? 'Joyfully accepts' : 'Regretfully declines']];
        if (response.attendance === 'yes') {
          details.push(['Guests', String(response.guests)]);
          if (response.dietary) details.push(['Dietary needs', response.dietary]);
        }
        for (const [label, value] of details) {
          const term = document.createElement('dt');
          const description = document.createElement('dd');
          term.textContent = label;
          description.textContent = value;
          summary.append(term, description);
        }
        if (focus) document.getElementById('confirmation-heading').focus();
      }
      name.addEventListener('blur', validateName);
      name.addEventListener('input', () => { if (name.hasAttribute('aria-invalid')) validateName(); });
      count.addEventListener('input', updateCount);
      count.addEventListener('blur', validateCount);
      form.querySelectorAll('[name=\"attendance\"]').forEach(input => input.addEventListener('change', updateAttendance));
      document.getElementById('increase').addEventListener('click', () => {
        count.value = Math.max(1, (Number(count.value) || 0) + 1);
        updateCount(); validateCount();
      });
      decrease.addEventListener('click', () => {
        count.value = Math.max(1, (Number(count.value) || 1) - 1);
        updateCount(); validateCount();
      });
      form.addEventListener('submit', event => {
        event.preventDefault();
        const nameValid = validateName();
        const attending = attendance();
        document.getElementById('attendance-error').hidden = "'!!attending;
        form.querySelectorAll('"'[name=\"attendance\"]').forEach(input => {
          if ("'!attending) input.setAttribute('"'aria-invalid', 'true');
          else input.removeAttribute('aria-invalid');
        });
        const countValid = attending === 'no' || validateCount();
        if ("'!nameValid || !attending || !countValid) {
          if (!nameValid) name.focus();
          else if (!attending) form.querySelector('"'[name=\"attendance\"]').focus();
          else count.focus();
          return;
        }
        const response = { name: name.value.trim(), attendance: attending, guests: attending === 'yes' ? Number(count.value) : 0, dietary: attending === 'yes' ? dietary.value.trim() : '' };
        try {
          localStorage.setItem(storageKey, JSON.stringify(response));
          document.getElementById('save-error').hidden = true;
          showConfirmation(response);
        } catch {
          document.getElementById('save-error').hidden = false;
        }
      });
      document.getElementById('edit-response').addEventListener('click', () => {
        confirmation.hidden = true;
        formSection.hidden = false;
        name.focus();
      });
      try {
        const saved = JSON.parse(localStorage.getItem(storageKey));
        if (saved && typeof saved.name === 'string' && saved.name.trim() && ['yes', 'no'].includes(saved.attendance) && (saved.attendance === 'no' || (Number.isSafeInteger(saved.guests) && saved.guests >= 1))) {
          name.value = saved.name;
          form.querySelector("'`input[value="${saved.attendance}"]`).checked = true;
          count.value = saved.guests || 1;
          dietary.value = typeof saved.dietary === '"'string' ? saved.dietary : '';
          updateAttendance(); updateCount(); showConfirmation(saved, false);
        }
      } catch { /* The form remains usable when browser storage is unavailable. */ }
    })();
  </script>
</body>
</html>
EOF"

